/** CC0 radio voice snippets. Sources and processing: ATTRIBUTION.txt. */
const decode=(b64,rate)=>{const raw=atob(b64),data=new Float32Array(raw.length/2);for(let i=0;i<data.length;i++){let n=raw.charCodeAt(i*2)|(raw.charCodeAt(i*2+1)<<8);if(n>32767)n-=65536;data[i]=n/32768;}return {data,rate};};
export const RADIO_KIT={radioPriority:decode('',24000),radioCall:decode('',24000),radioReply:decode('',24000)};

// V11 recorded radio additions. Author and license details: ATTRIBUTION.txt.
Object.assign(RADIO_KIT,{radioReply1:decode('',24000),radioReply3:decode('',24000),radioIn:decode('',24000),radioAffirmative:decode('',24000),radioRoger:decode('',24000),radioStanding:decode('',24000)});
